<template><PageShell title="考勤记录" description="按排班批量生成月考勤，再手工录入上下班、迟到、早退、缺勤与加班时长。" @refresh="load">
  <div class="toolbar"><el-date-picker :model-value="store.startDate" value-format="YYYY-MM-DD" placeholder="开始日期" clearable @update:model-value="changeStartDate"/><span>至</span><el-date-picker :model-value="store.endDate" value-format="YYYY-MM-DD" placeholder="结束日期" clearable @update:model-value="changeEndDate"/><el-button type="primary" :loading="store.saving" @click="generate">按排班批量生成</el-button><el-button @click="openCreate">手工新增</el-button></div>
  <el-table :data="store.attendance" empty-text="暂无考勤记录"><el-table-column prop="date" label="日期" width="115"/><el-table-column label="员工" width="110"><template #default="{row}">{{nameOf(row.employeeId)}}</template></el-table-column><el-table-column label="排班" width="90"><template #default="{row}">{{row.isScheduledWorkday?`${row.scheduledMinutes/60}小时`:'休息'}}</template></el-table-column><el-table-column label="上班" min-width="155"><template #default="{row}">{{punchText(row.checkInAt)}}</template></el-table-column><el-table-column label="下班" min-width="155"><template #default="{row}">{{punchText(row.checkOutAt)}}</template></el-table-column><el-table-column prop="lateMinutes" label="迟到" width="75"/><el-table-column prop="earlyLeaveMinutes" label="早退" width="75"/><el-table-column prop="absenceMinutes" label="缺勤" width="75"/><el-table-column prop="overtimeMinutes" label="加班" width="75"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" :disabled="!!row.lockedAt" @click="openEdit(row)">编辑</el-button><el-button link type="danger" :disabled="!!row.lockedAt" @click="remove(row.id)">删除</el-button></template></el-table-column></el-table>
</PageShell><el-dialog v-model="visible" :title="editingId?'编辑考勤':'新增考勤'" width="720px" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" class="form-grid"><el-form-item label="员工" required><el-select v-model="form.employeeId"><el-option v-for="row in store.employees" :key="row.id" :label="row.name" :value="row.id"/></el-select></el-form-item><el-form-item label="日期" required><el-date-picker v-model="form.date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="是否排班"><el-switch v-model="form.isScheduledWorkday"/></el-form-item><el-form-item label="排班分钟"><el-input-number v-model="form.scheduledMinutes" :min="0"/></el-form-item><el-form-item label="上班时间"><el-date-picker v-model="form.checkInAt" data-testid="attendance-check-in" type="datetime" format="YYYY-MM-DD HH:mm" value-format="YYYY-MM-DDTHH:mm" clearable/></el-form-item><el-form-item label="下班时间"><el-date-picker v-model="form.checkOutAt" data-testid="attendance-check-out" type="datetime" format="YYYY-MM-DD HH:mm" value-format="YYYY-MM-DDTHH:mm" clearable/></el-form-item><el-form-item v-for="field in minuteFields" :key="field.key" :label="field.label"><el-input-number v-model="form[field.key]" :min="0"/></el-form-item><el-form-item label="备注" class="wide"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="store.saving" @click="save">保存</el-button></template></el-dialog></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import dayjs from'dayjs';import{ElMessage}from'element-plus';import PageShell from'./EmployeeAttendancePageShell.vue';import{useEmployeeAttendanceStore}from'@/stores/employeeAttendance';import*as api from'@/api/employeeAttendance';import type{AttendancePayload,AttendanceRecord}from'@/types/employeeAttendance';const store=useEmployeeAttendanceStore(),visible=ref(false),editingId=ref(''),formError=ref('');const blank=():AttendancePayload=>({employeeId:store.employeeId||store.employees[0]?.id||'',date:dayjs().format('YYYY-MM-DD'),isScheduledWorkday:true,scheduledMinutes:480,checkInAt:'',checkOutAt:'',workedMinutes:0,lateMinutes:0,earlyLeaveMinutes:0,absenceMinutes:0,overtimeMinutes:0,remark:''});const form=reactive<AttendancePayload>(blank());const minuteFields=[{key:'workedMinutes',label:'实际工作分钟'},{key:'lateMinutes',label:'迟到分钟'},{key:'earlyLeaveMinutes',label:'早退分钟'},{key:'absenceMinutes',label:'缺勤分钟'},{key:'overtimeMinutes',label:'加班分钟'}]as const;const errorText=(error:unknown,fallback:string)=>error instanceof Error?error.message:fallback;function nameOf(id:string){return store.employees.find(row=>row.id===id)?.name||'-'}function punchText(value?:string|null){const local=api.toBeijingDateTimeLocal(value);return local?local.replace('T',' '):'未录入'}async function load(){await store.loadAttendance().catch(()=>undefined)}async function changeStartDate(value:unknown){store.selectDateRange(typeof value==='string'?value:'',store.endDate);await load()}async function changeEndDate(value:unknown){store.selectDateRange(store.startDate,typeof value==='string'?value:'');await load()}function openCreate(){editingId.value='';Object.assign(form,blank());formError.value='';visible.value=true}function openEdit(row:AttendanceRecord){editingId.value=row.id;Object.assign(form,row,{checkInAt:api.toBeijingDateTimeLocal(row.checkInAt),checkOutAt:api.toBeijingDateTimeLocal(row.checkOutAt)});formError.value='';visible.value=true}async function save(){if(!form.employeeId||!form.date){formError.value='员工和日期必填';return}try{await store.run(()=>api.saveAttendance({...form},editingId.value||undefined),true);visible.value=false;await load()}catch(error){formError.value=errorText(error,'保存失败')}}async function generate(){if(!store.month){store.setError('请先选择需要批量生成的月份');return}const targetMonth=store.month;store.selectMonth(targetMonth);const ids=store.employeeId?[store.employeeId]:store.activeEmployees.map(row=>row.id);if(!ids.length){store.setError('没有可生成的员工');return}try{const result=await store.run(()=>api.generateAttendance(targetMonth,ids),true);await load();ElMessage.success(`生成 ${result.created} 条，更新 ${result.updated} 条，跳过手工记录 ${result.skippedManual} 条`)}catch(error){store.setError(errorText(error,'批量生成失败'))}}async function remove(id:string){try{await store.run(()=>api.deleteAttendance(id),true);await load()}catch(error){store.setError(errorText(error,'考勤记录删除失败'))}}onMounted(load);
</script>
